-- Traductions françaises HomeCraft (NON OFFICIELLES) des quêtes restées en anglais dans la base VMaNGOS.
-- Rédigées pour HomeCraft Edition Vanilla le 2026-10-15. Seuls les champs vides sont remplis : les traductions
-- déjà présentes (dont les textes officiels) ne sont jamais écrasées. Balises du jeu conservées ($N $C $R $B $G…).
-- Appliqué par le launcher après l'import de la base monde (Server/Database/custom/*.sql).

CREATE TEMPORARY TABLE IF NOT EXISTS hc_q (
  entry INT UNSIGNED PRIMARY KEY, t TEXT, d TEXT, o TEXT, r TEXT, p TEXT, o1 TEXT, o2 TEXT, o3 TEXT
) DEFAULT CHARSET utf8mb3;
DELETE FROM hc_q;


-- Textes (description, objectifs, remise, progression) encore vides après la première passe.
ON DUPLICATE KEY UPDATE
  t = COALESCE(t, VALUES(t)), d = COALESCE(d, VALUES(d)), o = COALESCE(o, VALUES(o)), r = COALESCE(r, VALUES(r)),
  p = COALESCE(p, VALUES(p)), o1 = COALESCE(o1, VALUES(o1)), o2 = COALESCE(o2, VALUES(o2)), o3 = COALESCE(o3, VALUES(o3));

-- Création des lignes absentes, puis remplissage des seuls champs vides.
UPDATE locales_quest l JOIN hc_q h ON h.entry = l.entry SET
  l.Title_loc2            = IF(COALESCE(l.Title_loc2,'')='',            COALESCE(h.t,  l.Title_loc2),            l.Title_loc2),
  l.Details_loc2          = IF(COALESCE(l.Details_loc2,'')='',          COALESCE(h.d,  l.Details_loc2),          l.Details_loc2),
  l.Objectives_loc2       = IF(COALESCE(l.Objectives_loc2,'')='',       COALESCE(h.o,  l.Objectives_loc2),       l.Objectives_loc2),
  l.OfferRewardText_loc2  = IF(COALESCE(l.OfferRewardText_loc2,'')='',  COALESCE(h.r,  l.OfferRewardText_loc2),  l.OfferRewardText_loc2),
  l.RequestItemsText_loc2 = IF(COALESCE(l.RequestItemsText_loc2,'')='', COALESCE(h.p,  l.RequestItemsText_loc2), l.RequestItemsText_loc2),
  l.ObjectiveText1_loc2   = IF(COALESCE(l.ObjectiveText1_loc2,'')='',   COALESCE(h.o1, l.ObjectiveText1_loc2),   l.ObjectiveText1_loc2),
  l.ObjectiveText2_loc2   = IF(COALESCE(l.ObjectiveText2_loc2,'')='',   COALESCE(h.o2, l.ObjectiveText2_loc2),   l.ObjectiveText2_loc2),
  l.ObjectiveText3_loc2   = IF(COALESCE(l.ObjectiveText3_loc2,'')='',   COALESCE(h.o3, l.ObjectiveText3_loc2),   l.ObjectiveText3_loc2);
DROP TEMPORARY TABLE hc_q;

-- Dialogues de PNJ (broadcast_text) restés en anglais : grognements d'animaux et plantes de Gangrebois.
ON DUPLICATE KEY UPDATE
  male_text_loc2   = IF(COALESCE(male_text_loc2,'')='',   VALUES(male_text_loc2),   male_text_loc2),
  female_text_loc2 = IF(COALESCE(female_text_loc2,'')='', VALUES(female_text_loc2), female_text_loc2);
