INSERT INTO hc_q (entry, t, d, o, r, p, o1, o2, o3) VALUES
(8856, 'Kits de survie dans le désert', 'L\'arrivée de nouvelles recrues à Fort Cénarien pose le problème de leur survie dans le désert. La déshydratation et de nombreuses créatures venimeuses représentent une menace sérieuse pour des volontaires inexpérimentés. Rassemblez le nécessaire pour composer un kit de survie dans le désert et apportez-le à Calandrath, à Fort Cénarien.', 'Apportez 4 Globes d\'eau, 4 Puissants antivenins et 4 Saumons cuits à Calandrath, à l\'auberge de Fort Cénarien, en Silithus.', NULL, NULL, NULL, NULL, NULL),
(1099, 'Victoire des gobelins !', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1174, 'Victoire des gnomes !', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3111, 'Rune glyphique', 'Il y a longtemps, les hauts-elfes nous ont enseigné les secrets de la magie, à nous et à nos alliés humains. Ils nous ont fait la leçon sur les règles, et sur la façon dont la magie peut vous rendre fou ! Mais n\'en croyez rien. Nous ne sommes pas comme les elfes ; nous n\'avons pas les mêmes faiblesses. Restez sur le droit chemin et vous verrez que la magie est un outil aussi puissant qu\'une arme.$B$BQuand vous serez prêt, venez me trouver à l\'intérieur d\'Anvilmar. Je vous y attendrai !', 'Parlez à Marryk Nurribit à l\'intérieur d\'Anvilmar.', NULL, NULL, NULL, NULL, NULL),
(7797, 'Déchireur dimensionnel - Everlook', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7961, 'Ces sacrés lapins !', 'Ces lapins se reproduisent sans aucun contrôle. Il faut faire quelque chose !$B$BAidez-nous, $N, vous êtes notre seul espoir.', 'Tuez 5 lapins et retournez voir Jon LeCraft près de la forge, sur l\'île des concepteurs.', NULL, NULL, NULL, NULL, NULL),
(7962, 'Peaux de lapin', 'Je veux des peaux de lapin LeCrafty. Prenez-en sur les lapins LeCrafty.$B$BC\'est important !', 'Apportez 3 Peaux de lapin LeCrafty à Jon LeCraft.', NULL, NULL, NULL, NULL, NULL),
(8001, 'Purge des zombies', 'Je suis Corpus et vous êtes un bien misérable spécimen, OUI ! Vous ferez parfaitement l\'affaire. Cette ville est devenue surpeuplée et il est de plus en plus difficile d\'y trouver une tombe vide. Pouvez-vous m\'aider à me débarrasser de quelques-uns des immondes zombies qui infestent mes tombes ? Cinq devraient suffire à me garantir une place pour reposer.', 'Tuez 5 Zombies misérables.', NULL, NULL, NULL, NULL, NULL),
(1, 'La quête du « Chow » (123)aa', '$Tpunk; ! Tuez de la Vermine kobold, 2 d\'entre elles. NOUVEAU TEST', 'Tuez 2 Vermines kobolds.', NULL, NULL, NULL, NULL, NULL),
(3903, 'Milly Osworth', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(9065, 'La quête du « Chow » (123)aa', '$Tpunk; ! Tuez de la Vermine kobold, 2 d\'entre elles.', 'Tuez 2 Vermines kobolds.', NULL, NULL, NULL, NULL, NULL),
