(766, 'Mazzranache', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(785, 'Une alliance stratégique', 'Thrall est un chef des plus sages et des plus nobles. Sa ténacité sur le champ de bataille n\'a d\'égale que son sens de la diplomatie.$B$BLes trolls Sombrelance se sont révélés des alliés inestimables pour le peuple orc. Par loyauté et par honneur, nous avons juré de les protéger.$B$BLe chef de guerre a donné l\'ordre de s\'assurer que nos amis Sombrelance du village de Sen\'jin ne subissent aucune menace directe. L\'un de leurs éclaireurs les plus fiables, Lar Prowltusk, surveille de près leur flanc ouest.$B$BTrouvez Lar et aidez-le selon les besoins.', 'Trouvez Lar Prowltusk sur le flanc ouest du village de Sen\'jin.', NULL, NULL, NULL, NULL, NULL),
