(894, 'Samophlange', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(900, 'Samophlange', NULL, NULL, NULL, NULL, 'Fermez la vanne de contrôle principale', 'Fermez la vanne de carburant', 'Fermez la vanne du régulateur'),
(901, 'Samophlange', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8290, 'Repoussez les envahisseurs', 'Au-delà de ce tunnel, vous trouverez un champ de discorde et de tourments, jeune $C. La Horde continue de ravager notre forêt sacrée, abattant les arbres toujours verts pour alimenter ses machines de guerre.$B$BEntrez dans le goulet des Chanteguerres et défendez le fort d\'Aile-argent. Repoussez les forces d\'invasion de la Horde !$B$BFaites cela, et gagnez un talisman de vaillance. Apportez-moi ce talisman, $N, et je vous récompenserai.', 'Entrez dans le goulet des Chanteguerres et vainquez la Horde, obtenez une Marque d\'honneur du goulet des Chanteguerres et revenez voir la sentinelle Farsong au bosquet d\'Aile-argent.', NULL, NULL, NULL, NULL, NULL),
(8295, 'Matez les usurpateurs d\'Aile-argent', 'Les étendues sauvages de la forêt d\'Orneval succomberont à la puissance de la Horde, $R. Rien de ce que disent ou font les Aile-argent ne peut arrêter notre impératif souverain. Kalimdor appartient à la Horde. Comment osent-ils tenter de nous empêcher de récolter ce qui nous revient de droit !$B$BQue la fierté gonfle votre poitrine tandis que vous fauchez leurs faibles tentatives de ralentir notre progression. Détruisez les sentinelles d\'Aile-argent et gagnez une marque d\'honneur des Chanteguerres. Revenez me voir avec une telle marque, $N, et vous serez récompensé.', 'Entrez dans le goulet des Chanteguerres et vainquez l\'Alliance, obtenez une Marque d\'honneur du goulet des Chanteguerres et apportez-la au capitaine Crâne-brisé au camp de base de Mor\'shan.', NULL, NULL, NULL, NULL, NULL),
(881, 'Echeyakee', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(902, 'Samophlange', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1998, 'Fenwick Thatros', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2300, 'SI:7', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2379, 'Zando\'zan', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(948, 'Onu', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1006, 'Ce qui se cache au-delà', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(882, 'Ishamuhale', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1005, 'Ce qui rôde au-delà', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5678, 'Retour de flamme arcanique', 'Il est temps pour vous de retourner à Hurlevent, jeune $C. Vos supérieurs vous y rappellent pour poursuivre votre formation. Et même si cela me dérange un peu, votre peuple et le mien sont alliés, et je ne trahirai pas cela.$B$BJe ne cherche pas à être évasif avec vous : ma méfiance envers les magies arcaniques, qu\'elles soient d\'inspiration divine ou non, est encore forte en moi.$B$BVous comprendrez de quoi je parle une fois de retour à votre cathédrale de la Lumière. Parlez à la grande prêtresse Laurena à votre arrivée.', 'Parlez à la grande prêtresse Laurena à Hurlevent.', 'Ah, vous tombez à pic, $N. Je commençais à me demander si tous mes messagers avaient réussi. Je suis ravie de voir que c\'est le cas, sinon je parierais que vous seriez encore de par le monde à en apprendre davantage sur toutes les menaces qui pèsent sur notre peuple.$B$BÊtes-vous prêt ? Prêt à poursuivre votre formation, je veux dire. Votre puissance grandit de plus en plus vite, et je sens que vous êtes prêt à en apprendre davantage sur notre foi.', NULL, NULL, NULL, NULL),
(236, 'Dans l\'attente de nouvelles', 'Il y a quelques semaines, j\'ai envoyé le guetteur Callahan et quelques hommes à la frontière nord du bois de la Pénombre pour s\'occuper de l\'infestation de loups. Je n\'ai pas eu de nouvelles de lui depuis un bon moment. S\'il a suivi mes instructions, il campe sur la route qui part de Sombrecomté vers le nord.$B$BSi c\'est sur votre chemin, allez voir comment il va et dites-lui que j\'attends son rapport.', 'Parlez au guetteur Callahan.', NULL, NULL, NULL, NULL, NULL),
