(206, 'Mai\'Zoth', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3381, 'Une rencontre avec le maître', NULL, 'Apportez 2 Plumes d\'hippogryphe intactes à Sanath Lim-yo, en Azshara, si vous souhaitez parler à son maître.', NULL, NULL, NULL, NULL, NULL),
(2770, 'Gahz\'rilla', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6000, 'Serment à Gakin', '$N ! Je ne m\'attendais pas à vous voir dans la région. Vous aviez pourtant reçu l\'instruction de rester sur vos gardes.$B$BIl est temps de poursuivre votre formation. Lors de votre prochain passage à Hurlevent, vous devrez vous présenter à Gakin.$B$BIl vous attend.', 'Présentez-vous à Gakin le Lieur d\'ombre, dans le quartier des mages de Hurlevent.', NULL, NULL, NULL, NULL, NULL),
(7704, 'Regardez la taille de ça !', 'Tiens, tiens, tiens... Quelle surprise. La femme de chambre possédait un gigantesque coussin brodé, et le voilà à vous. Evonice Sootsmoker voudra certainement y poser ses petites mains avides. Apportez-le-lui et voyez si elle vous offre quelque chose pour la peine.', 'Apportez le coussin de la femme de chambre Pillaclencher à Evonice Sootsmoker, dans la gorge des Vents brûlants.', NULL, NULL, NULL, NULL, NULL),
(3822, 'Krom\'Grul', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3911, 'Le dernier élément', 'Il y a du travail pour ceux qui s\'aventurent dans les profondeurs, $N.$B$BLes Sombrefer maîtrisent la création de golems extrêmement puissants.$B$BLes premiers rapports de nos espions indiquent que les nains utilisent une source d\'énergie unique pour donner à leurs créations une puissance meurtrière incomparable.$B$BImaginez ce que nous pourrions faire de nos abominations si nous mettions la main sur cette essence des éléments ! Retournez cette cité sens dessus dessous s\'il le faut, mais ne revenez pas avant d\'avoir trouvé l\'essence ! La récompense vaudra le risque.', 'Rendez-vous dans les Profondeurs de Rochenoire et récupérez 10 Essences des éléments. Votre premier réflexe est de fouiller les golems et leurs créateurs. Vous vous souvenez aussi que Vivian Lagrave a marmonné quelque chose à propos d\'élémentaires.', NULL, NULL, NULL, NULL, NULL),
(4005, 'Aquementas', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
