(7908, 'Maître de l\'arène', 'Être maître de l\'arène ne peut pas se résumer à ça ! Le pirate qui organise l\'événement à Gurubashi en saura peut-être davantage !', 'Parlez à Short John Mithril, à l\'arène de Strangleronce.', NULL, NULL, NULL, NULL, NULL),
(7922, 'Marque d\'honneur', NULL, 'Vous avez obtenu une Marque d\'honneur des Chanteguerres lors de votre dernière mission. Parlez-moi de nouveau pour recevoir votre récompense.', NULL, NULL, NULL, NULL, NULL),
