(7824, NULL, '$N, vous avez énormément contribué à notre collecte de tissu. Alors que nous travaillons dur pour reconstituer nos réserves, je dois vous faire part de notre pénurie la plus grave : l\'étoffe runique. Nous avons désespérément besoin d\'étoffe runique, et nous espérons que vous pourrez nous aider comme vous l\'avez fait par le passé.$BSi vous le voulez bien, apportez-moi l\'étoffe runique dont vous pouvez vous passer. Nous accepterons d\'abord un don de soixante pièces, et nous verrons ensuite.', 'Livrez 60 Étoffes runiques à Vehena.', NULL, NULL, NULL, NULL, NULL),
(7836, NULL, '$N, vous avez énormément contribué à notre collecte de tissu. Alors que nous travaillons dur pour reconstituer nos réserves, je dois vous faire part de notre pénurie la plus grave : l\'étoffe runique. Nous avons désespérément besoin d\'étoffe runique, et nous espérons que vous pourrez nous aider comme vous l\'avez fait par le passé.$BSi vous le voulez bien, apportez-moi l\'étoffe runique dont vous pouvez vous passer. Nous accepterons d\'abord un don de soixante pièces, et nous verrons ensuite.', 'Livrez 60 Étoffes runiques à Rashona Straglash.', NULL, NULL, NULL, NULL, NULL),
(7886, NULL, 'Vous avez prouvé votre valeur pour notre cause dans le goulet des Chanteguerres. Continuez à servir la cause et apportez-moi d\'autres talismans de vaillance. Faites cela, et vous gagnerez encore davantage notre confiance.', NULL, NULL, 'Vous avez obtenu un Talisman de vaillance d\'Aile-argent lors de votre dernière mission. Parlez-moi de nouveau pour recevoir votre récompense.', NULL, NULL, NULL),
(7887, NULL, 'Vous avez prouvé votre valeur pour notre cause dans le goulet des Chanteguerres. Continuez à servir la cause et apportez-moi d\'autres talismans de vaillance. Faites cela, et vous gagnerez encore davantage notre confiance.', NULL, NULL, 'Vous avez obtenu un Talisman de vaillance d\'Aile-argent lors de votre dernière mission. Parlez-moi de nouveau pour recevoir votre récompense.', NULL, NULL, NULL),
(7888, NULL, 'Vous avez prouvé votre valeur pour notre cause dans le goulet des Chanteguerres. Continuez à servir la cause et apportez-moi d\'autres talismans de vaillance. Faites cela, et vous gagnerez encore davantage notre confiance.', NULL, NULL, 'Vous avez obtenu un Talisman de vaillance d\'Aile-argent lors de votre dernière mission. Parlez-moi de nouveau pour recevoir votre récompense.', NULL, NULL, NULL),
(7921, NULL, 'Vous avez prouvé votre valeur pour notre cause dans le goulet des Chanteguerres. Continuez à servir la cause et apportez-moi d\'autres talismans de vaillance. Faites cela, et vous gagnerez encore davantage notre confiance.', NULL, NULL, 'Vous avez obtenu un Talisman de vaillance d\'Aile-argent lors de votre dernière mission. Parlez-moi de nouveau pour recevoir votre récompense.', NULL, NULL, NULL),
(7922, NULL, 'Vous avez prouvé votre valeur pour notre cause dans le goulet des Chanteguerres. Continuez à vous déchaîner contre les sentinelles d\'Aile-argent ! Apportez-moi d\'autres marques d\'honneur !', NULL, NULL, 'Votre dernière mission a été prise en compte. Apportez-moi d\'autres Marques d\'honneur et vous serez récompensé.', NULL, NULL, NULL),
(7923, NULL, 'Vous avez prouvé votre valeur pour notre cause dans le goulet des Chanteguerres. Continuez à vous déchaîner contre les sentinelles d\'Aile-argent ! Apportez-moi d\'autres marques d\'honneur !', NULL, NULL, 'Votre dernière mission a été prise en compte. Apportez-moi d\'autres Marques d\'honneur et vous serez récompensé.', NULL, NULL, NULL),
(7924, NULL, 'Vous avez prouvé votre valeur pour notre cause dans le goulet des Chanteguerres. Continuez à vous déchaîner contre les sentinelles d\'Aile-argent ! Apportez-moi d\'autres marques d\'honneur !', NULL, NULL, 'Votre dernière mission a été prise en compte. Apportez-moi d\'autres Marques d\'honneur et vous serez récompensé.', NULL, NULL, NULL),
(7925, NULL, 'Vous avez prouvé votre valeur pour notre cause dans le goulet des Chanteguerres. Continuez à vous déchaîner contre les sentinelles d\'Aile-argent ! Apportez-moi d\'autres marques d\'honneur !', NULL, NULL, 'Votre dernière mission a été prise en compte. Apportez-moi d\'autres Marques d\'honneur et vous serez récompensé.', NULL, NULL, NULL),
(8267, NULL, 'Je comprends qu\'il soit parfois difficile de l\'emporter dans le goulet des Chanteguerres. Pourtant, vos efforts en notre nom, même sans victoire, comptent.$B$BSi vous terminez l\'une des épreuves du goulet des Chanteguerres sans remporter la victoire, vous recevrez tout de même des Rubans de sacrifice. Apportez-les-moi pour que les Outriders puissent vous récompenser d\'avoir agi en notre nom... même si vous n\'avez pas pu gagner cette fois.', NULL, NULL, 'Je comprends qu\'il soit parfois difficile de l\'emporter dans le goulet des Chanteguerres. Pourtant, vos efforts en notre nom, même sans victoire, comptent.$B$BSi vous terminez l\'une des épreuves du goulet des Chanteguerres sans remporter la victoire, vous recevrez tout de même des Rubans de sacrifice. Apportez-les-moi pour que les Outriders puissent vous récompenser d\'avoir agi en notre nom... même si vous n\'avez pas pu gagner cette fois.', NULL, NULL, NULL),
(8269, NULL, 'Je comprends qu\'il soit parfois difficile de l\'emporter dans le goulet des Chanteguerres. Pourtant, vos efforts en notre nom, même sans victoire, comptent.$B$BSi vous terminez l\'une des épreuves du goulet des Chanteguerres sans remporter la victoire, vous recevrez tout de même des Rubans de sacrifice. Apportez-les-moi pour que les Sentinelles puissent vous récompenser d\'avoir agi en notre nom... même si vous n\'avez pas pu gagner cette fois.', NULL, NULL, 'Je comprends qu\'il soit parfois difficile de l\'emporter dans le goulet des Chanteguerres. Pourtant, vos efforts en notre nom, même sans victoire, comptent.$B$BSi vous terminez l\'une des épreuves du goulet des Chanteguerres sans remporter la victoire, vous recevrez tout de même des Rubans de sacrifice. Apportez-les-moi pour que les Sentinelles puissent vous récompenser d\'avoir agi en notre nom... même si vous n\'avez pas pu gagner cette fois.', NULL, NULL, NULL),
(8298, NULL, 'Une guerre se gagne avec des soldats, n\'importe quel soldat vous le dira. Il vous dira aussi qu\'une bataille livrée avec un mauvais équipement ou le ventre vide est perdue avant même d\'avoir commencé !$B$BVoilà pourquoi le bassin d\'Arathi est important. Il recèle des zones clés qui contiennent des ressources essentielles. Métaux, armes, nourriture, bois : tout cela est nécessaire, et tout cela peut y être obtenu.$B$BVoilà ce que j\'attends de vous, $N. Entrez dans le bassin d\'Arathi, remportez la bataille en tenant plus de bases que l\'ennemi, et revenez me voir avec une caisse de ressources.', 'Remportez la bataille du bassin d\'Arathi, obtenez une Caisse de ressources d\'Arathi et rapportez-la au sergent Maclear, au Pointe du Refuge.', NULL, NULL, NULL, NULL, NULL),
(8300, NULL, 'La Ligue d\'Arathor ne lésine pas sur les moyens pour reprendre l\'Arathi. Elle et toutes les races de l\'Alliance affluent maintenant vers cette région lointaine, bien décidées à étendre leur emprise depuis le Pointe du Refuge. Nous devons les arrêter, et le meilleur moyen d\'y parvenir est de nous emparer de leurs ressources.$B$BVous pouvez nous aider, $N. Entrez dans le bassin d\'Arathi, réputé pour ses mines riches, ses terres fertiles et ses artisans habiles. Capturez et contrôlez toutes les bases que vous pourrez, remportez la bataille, et revenez me voir avec les ressources gagnées.', 'Remportez la bataille du bassin d\'Arathi, obtenez une Caisse de ressources d\'Arathi et rapportez-la au Traque-mort Mortis, à Trépas-d\'Orgrim.', NULL, NULL, NULL, NULL, NULL),
(8306, NULL, NULL, NULL, NULL, 'Natalia ?', NULL, NULL, NULL),
(8506, NULL, NULL, NULL, 'J\'accepte avec plaisir votre contribution au nom de l\'Alliance, $N. Vos efforts permettront directement la fabrication de plusieurs potions et huiles destinées à nos hommes et nos femmes sur le terrain. Merci, et si vous en trouvez d\'autres, pensez à revenir me voir.', NULL, NULL, NULL, NULL),
(8510, NULL, NULL, NULL, 'Tout simplement remarquable, $N ! Vous faites vraiment honneur à l\'Alliance. Je veillerai à ce que ces herbes soient mises de côté jusqu\'à ce que quelqu\'un vienne en faire quelque chose d\'utile pour la guerre. N\'hésitez pas à repasser quand vous voulez, surtout si vous avez d\'autres Larmes d\'Arthas pour moi.', 'Bon, on dirait qu\'il me faut encore des Larmes d\'Arthas, $c. J\'imagine que vous pourrez en trouver à l\'endroit où vous les avez cueillies la dernière fois. L\'effort de guerre avance bien, mais plus vite nous les aurons, plus vite nous pourrons lancer l\'offensive contre les forces d\'Ahn\'Qiraj.$B$BVous allez nous aider encore une fois, $N ?', NULL, NULL, NULL),
(9257, NULL, NULL, NULL, 'L\'ampleur de cet exploit ne doit pas être sous-estimée, $N. Vous avez accompli ce que la plupart auraient cru impossible. Hélas, c\'était écrit. Le bâton a fait son choix...', 'Je ne dois pas intervenir, $R.', NULL, NULL, NULL),
(9269, NULL, NULL, NULL, 'L\'ampleur de cet exploit ne doit pas être sous-estimée, $N. Vous avez accompli ce que la plupart auraient cru impossible. Hélas, c\'était écrit. Le bâton a fait son choix...', 'Je ne dois pas intervenir, $R.', NULL, NULL, NULL),
(9270, NULL, NULL, NULL, 'L\'ampleur de cet exploit ne doit pas être sous-estimée, $N. Vous avez accompli ce que la plupart auraient cru impossible. Hélas, c\'était écrit. Le bâton a fait son choix...', 'Je ne dois pas intervenir, $R.', NULL, NULL, NULL),
(9271, NULL, NULL, NULL, 'L\'ampleur de cet exploit ne doit pas être sous-estimée, $N. Vous avez accompli ce que la plupart auraient cru impossible. Hélas, c\'était écrit. Le bâton a fait son choix...', 'Je ne dois pas intervenir, $R.', NULL, NULL, NULL)
